import { Package } from '@hexa-ui/icons';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import React from 'react';
import { Chip } from '../..';

describe('Chip', () => {
  test('should render without crash', () => {
    render(
      <Chip.Root>
        <Chip.Label label="I'm a chip" />
      </Chip.Root>
    );
    expect(screen.getByTestId('chip-container')).toBeInTheDocument();
  });

  test('should fire the onClick event when the chip is focused and the space key is pressed', () => {
    jest.spyOn(console, 'log').mockImplementation();
    render(
      <Chip.Root onClick={() => console.log("I'm clicked")}>
        <Chip.Label label="I'm a chip" />
      </Chip.Root>
    );
    fireEvent.keyPress(screen.getByTestId('chip-container'), { key: 'Space' });
    waitFor(() => expect(console.log).toHaveBeenCalledWith(expect.stringContaining("I'm clicked")));
  });

  test('should not fire the onClick event when the chip is focused and the P key is pressed', () => {
    jest.spyOn(console, 'log').mockImplementation();
    render(
      <Chip.Root onClick={() => console.log("I'm clicked")}>
        <Chip.Label label="I'm a chip" />
      </Chip.Root>
    );
    fireEvent.keyPress(screen.getByTestId('chip-container'), { key: 'p' });
    waitFor(() =>
      expect(console.log).not.toHaveBeenCalledWith(expect.stringContaining("I'm clicked"))
    );
  });

  test('should not fire the onClick event when the chip is focused and the Enter key is pressed with Chip disabled', () => {
    jest.spyOn(console, 'log').mockImplementation();
    render(
      <Chip.Root disabled onClick={() => console.log("I'm clicked")}>
        <Chip.Label label="I'm a chip" />
      </Chip.Root>
    );
    fireEvent.keyPress(screen.getByTestId('chip-container'), { key: 'Enter' });
    waitFor(() =>
      expect(console.log).not.toHaveBeenCalledWith(expect.stringContaining("I'm clicked"))
    );
  });

  test('should fire the onClick event when the chip is focused and the enter key is pressed', () => {
    jest.spyOn(console, 'log').mockImplementation();
    render(
      <Chip.Root onClick={() => console.log("I'm clicked")}>
        <Chip.Label label="I'm a chip" />
      </Chip.Root>
    );
    fireEvent.keyPress(screen.getByTestId('chip-container'), { key: 'Space' });
    waitFor(() => expect(console.log).toHaveBeenCalledWith(expect.stringContaining("I'm clicked")));
  });

  test('should fire the onClick event when the chip is clicked', () => {
    jest.spyOn(console, 'log').mockImplementation();
    render(
      <Chip.Root onClick={() => console.log("I'm clicked")}>
        <Chip.Label label="I'm a chip" />
      </Chip.Root>
    );
    fireEvent.click(screen.getByTestId('chip-container'));
    expect(console.log).toHaveBeenCalledWith(expect.stringContaining("I'm clicked"));
  });

  test('should fire the onDelete event when the delete icon is clicked', () => {
    jest.spyOn(console, 'log').mockImplementation();
    render(
      <Chip.Root>
        <Chip.Icon icon={() => <Package />} />
        <Chip.Label label="I'm a chip" />
        <Chip.DeleteIcon onDelete={() => console.log("I'm deleted")} />
      </Chip.Root>
    );
    fireEvent.click(screen.getByTestId('chip-delete-icon'));
    expect(console.log).toHaveBeenCalledWith(expect.stringContaining("I'm deleted"));
  });
});
